-- Approvals organ -- generated by noctusai_lib.domain.approvals.sql
SET search_path = social_wiring, public;
-- Events: APPEND-ONLY. Every submission and every decision on a (subject, versao) is a row (who, when, why).
CREATE TABLE IF NOT EXISTS social_wiring.apr_events (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    subject_kind TEXT NOT NULL CHECK (subject_kind ~ '^[a-z][a-z0-9_]{0,39}$'),
    subject_id   UUID NOT NULL,
    versao       INTEGER NOT NULL,
    event        TEXT NOT NULL,
    actor_id     UUID,
    motivo       TEXT,
    note         TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT apr_events_kind CHECK (event IN ('submitted', 'approved', 'rejected')),
    CONSTRAINT apr_events_versao_positive CHECK (versao > 0),
    CONSTRAINT apr_events_reject_motivo CHECK (event <> 'rejected' OR length(btrim(coalesce(motivo, ''))) > 0)
);
-- A versao is submitted once and decided once: structural, so a concurrent double decision loses instead of duplicating.
CREATE UNIQUE INDEX IF NOT EXISTS uq_apr_events_submitted ON social_wiring.apr_events (org_id, subject_kind, subject_id, versao) WHERE event = 'submitted';
CREATE UNIQUE INDEX IF NOT EXISTS uq_apr_events_decided ON social_wiring.apr_events (org_id, subject_kind, subject_id, versao) WHERE event IN ('approved', 'rejected');
CREATE INDEX IF NOT EXISTS idx_apr_events_subject ON social_wiring.apr_events (org_id, subject_kind, subject_id, created_at);
CREATE INDEX IF NOT EXISTS idx_apr_events_when ON social_wiring.apr_events (org_id, created_at DESC);
CREATE OR REPLACE FUNCTION social_wiring.apr_events_append_only()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, social_wiring, pg_temp
AS $$ BEGIN RAISE EXCEPTION 'apr_events is append-only' USING ERRCODE = 'insufficient_privilege'; END; $$;
REVOKE ALL ON FUNCTION social_wiring.apr_events_append_only() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION social_wiring.apr_events_append_only() TO service_role;
DROP TRIGGER IF EXISTS apr_events_append_only ON social_wiring.apr_events;
CREATE TRIGGER apr_events_append_only
    BEFORE UPDATE OR DELETE ON social_wiring.apr_events
    FOR EACH ROW EXECUTE FUNCTION social_wiring.apr_events_append_only();
COMMENT ON TABLE social_wiring.apr_events IS 'tier:org';
ALTER TABLE social_wiring.apr_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "apr_events_select_own_org" ON social_wiring.apr_events;
DROP POLICY IF EXISTS "service_role_bypass" ON social_wiring.apr_events;
CREATE POLICY "service_role_bypass" ON social_wiring.apr_events FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON social_wiring.apr_events FROM PUBLIC, anon, authenticated;
GRANT ALL ON social_wiring.apr_events TO service_role;

-- Record one approvals event atomically.
-- `p_row`: subject_kind, subject_id, versao, event ('submitted' | 'approved' | 'rejected'), actor_id?, motivo?, note?
-- submitted: the same versao again is a no-op; a lower one is stale. approved / rejected: the versao must be the current one and undecided.
CREATE OR REPLACE FUNCTION social_wiring.apr_record(p_org UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, social_wiring, pg_temp
AS $fn$
DECLARE
    v_kind    TEXT := p_row->>'subject_kind';
    v_subject UUID := (p_row->>'subject_id')::uuid;
    v_versao  INTEGER := (p_row->>'versao')::integer;
    v_event   TEXT := p_row->>'event';
    v_current INTEGER;
    v_row     social_wiring.apr_events%ROWTYPE;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || v_kind || ':' || v_subject::text, 0));
    SELECT max(versao) INTO v_current FROM social_wiring.apr_events
     WHERE org_id = p_org AND subject_kind = v_kind AND subject_id = v_subject AND event = 'submitted';

    IF v_event = 'submitted' THEN
        IF v_current IS NOT NULL AND v_versao = v_current THEN
            RETURN jsonb_build_object('changed', false, 'event', NULL, 'versao', v_current);
        END IF;
        IF v_current IS NOT NULL AND v_versao < v_current THEN
            RAISE EXCEPTION 'apr_stale_versao' USING ERRCODE = 'P0001';
        END IF;
    ELSIF v_event IN ('approved', 'rejected') THEN
        IF v_current IS NULL THEN
            RAISE EXCEPTION 'apr_not_submitted' USING ERRCODE = 'P0002';
        END IF;
        IF v_versao <> v_current THEN
            RAISE EXCEPTION 'apr_stale_versao' USING ERRCODE = 'P0001';
        END IF;
        IF EXISTS (SELECT 1 FROM social_wiring.apr_events WHERE org_id = p_org AND subject_kind = v_kind AND subject_id = v_subject
                      AND versao = v_versao AND event IN ('approved', 'rejected')) THEN
            RAISE EXCEPTION 'apr_already_decided' USING ERRCODE = 'P0001';
        END IF;
    ELSE
        RAISE EXCEPTION 'apr_record: unknown event' USING ERRCODE = '22023';
    END IF;

    INSERT INTO social_wiring.apr_events (org_id, subject_kind, subject_id, versao, event, actor_id, motivo, note)
    VALUES (p_org, v_kind, v_subject, v_versao, v_event, nullif(p_row->>'actor_id', '')::uuid,
            nullif(btrim(p_row->>'motivo'), ''), p_row->>'note')
    RETURNING * INTO v_row;
    RETURN jsonb_build_object('changed', true, 'event', v_event, 'versao', v_versao, 'row', to_jsonb(v_row));
END;
$fn$;
REVOKE EXECUTE ON FUNCTION social_wiring.apr_record(UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION social_wiring.apr_record(UUID, JSONB) TO service_role;
